    def render(self, mode: str = 'human') -> None:
        """Render current state"""

        if len(self.state_history) == 0:
            return

        self._save_frame(self.step_count, "render")

    def close(self) -> None:
        """Clean up environment"""

        try:
            femm.closefemm()
        except:
            pass

        self.logger.info("Environment closed")

